+    { scenario: "error", ok: true },
+    { scenario: "unavailable", ok: false },
+  ];
+  for (const { scenario, ok } of cases) {
+    const renderer = createFixtureRenderer({ latencyMs: 0, scenario });
+    if (ok) {
+      assert.deepEqual(await renderer.ping(), { available: true });
