          onAddVariant={onAddVariant}
          onOpenVariant={(font, variant) => openVariantId(font.id, variant.id)}
          onDeleteFont={onDeleteFont}
          onImport={onImport}
          onFilter={setIndexFilter}
          onSampleText={(text) => onLibraryPreferences({ text })}
