import type { RenderPixels } from "../../src/app/renderer/client.ts";
import type { RenderSpec } from "../../src/app/renderer/renderer-types.ts";

function spec({
  text = "A",
  width = 12,
  height = 2,
  size_px = 10,
  axes = {},
  hinting = "auto",
  output_bits = 1,
  mono_threshold = 128,
  gray_gamma = 1,
  missing_glyphs = "error",
  kerning = true,
  metric_rounding = "subpixel",
  wrap = "clip",
  align = "left",
  foreground = [36, 40, 43, 255],
  background = [255, 255, 255, 255],
  palette = undefined,
  letter_spacing_px = 0,
}: Partial<RenderSpec> = {}): RenderSpec {
  return {
    text,
    width,
    height,
    size_px,
    axes,
    hinting,
    output_bits,
    mono_threshold,
    gray_gamma,
    missing_glyphs,
    kerning,
    metric_rounding,
    wrap,
    align,
    foreground,
    background,
    letter_spacing_px,
    ...(palette === undefined ? {} : { palette }),
  };
}

function at(
  pixels: RenderPixels,
  x: number,
  y: number,
): [number, number, number, number] {
  const view = new Uint8Array(pixels.pixels);
  const offset = (y * pixels.width + x) * 4;
  const r = view[offset];
  const g = view[offset + 1];
  const b = view[offset + 2];
  const a = view[offset + 3];
  if (r === undefined || g === undefined || b === undefined || a === undefined) {
    throw new Error(`pixel out of range at (${x}, ${y})`);
  }
  return [r, g, b, a];
}

