    paletteId: snapshot.paletteId ?? 0,
    kerning: snapshot.kerning,
    stemFitting: snapshot.stemFitting,
    diagonalFitting: snapshot.diagonalFitting ?? false,
    monoRaster: snapshot.monoRaster,
    rasterization: snapshot.rasterization,
