export function encodeHashSearch(
  snapshot: PreviewSnapshot,
  baseSearch: string | URLSearchParams,
  familyOrder?: string[],
): URLSearchParams {
  const params = encodeUrlSnapshot(snapshot, baseSearch, familyOrder);
  params.delete("font");
  return params;
}

