export type FixtureScenario = "ok" | "missing-glyphs" | "error" | "unavailable";

export interface FixtureRendererOptions {
  scenario?: FixtureScenario;
  latencyMs?: number;
  lineHeight?: number;
  events?: FixtureRendererEvents;
