    "  spacing={0}",
    "  kerning",
    '  stemFitting="font_hints_first"',
    '  monoRaster={{ dropout: "smart", includeStubs: false, fontInstructions: false }}',
    `  zoom={${args.zoom}}`,
    `  mode="${args.mode}"`,
    ...(args.palette === undefined ? [] : [`  palette={[${args.palette.map(tuple).join(", ")}]}`]),
