  // it so a recreated worker never serves stale readiness or results.
  session: number;
  available: boolean | null;
  availabilityError: string;
}

const RendererContext = React.createContext<RendererContextValue | null>(null);

export function useRenderer(): RendererContextValue {
  const value = React.useContext(RendererContext);
  if (!value) throw new Error("useRenderer must be used inside <RendererProvider>.");
  return value;
}

let sessionCounter = 0;

interface RendererProviderProps {
  children: React.ReactNode;
  createService: () => RendererService;
}

// Owns the single active worker. Creation and termination happen inside this
// effect (never during render), so StrictMode setup-cleanup-setup cannot leak
// a worker or leave a terminated one active. A changed factory is deliberate
// replacement: the active worker is terminated and a new session starts, so
// exactly one worker is ever live. A synchronously throwing factory marks the
// renderer unavailable instead of crashing the tree.
export function RendererProvider({ children, createService }: RendererProviderProps): React.JSX.Element {
  const [service, setService] = React.useState<RendererService | null>(null);
  const [session, setSession] = React.useState(0);
  const [available, setAvailable] = React.useState<boolean | null>(null);
  const [availabilityError, setAvailabilityError] = React.useState("");

  React.useEffect(() => {
    let next: RendererService | null = null;
    try {
      next = createService();
    } catch (error) {
      setService(null);
      setAvailable(false);
      setAvailabilityError(error instanceof Error ? error.message : String(error ?? ""));
      return;
    }
    const active = next;
    sessionCounter += 1;
    const nextSession = sessionCounter;
    let live = true;
    setService(active);
    setSession(nextSession);
    setAvailable(null);
    setAvailabilityError("");
    active.ping().then(
      () => { if (live) setAvailable(true); },
      (error: unknown) => {
        if (!live) return;
        setAvailable(false);
        setAvailabilityError(error instanceof Error ? error.message : String(error ?? ""));
      },
    );
    return () => {
      live = false;
      active.terminate();
      setService((current) => (current === active ? null : current));
    };
  }, [createService]);

  const value = React.useMemo(
    () => ({ service, session, available, availabilityError }),
    [service, session, available, availabilityError],
  );
  return <RendererContext.Provider value={value}>{children}</RendererContext.Provider>;
}
// Typed boundary for the staged wasm-bindgen renderer (tools/wasm). The
// generated font_wasm.d.ts types render specs as `any`; this declaration
// gives the browser code the exact shape the Rust side serializes
// (tools/wasm/src/lib.rs RenderSpec). Only the surface the interactive
// renderer uses is declared. Type-only module: imports of it are erased at
// compile time.

import type { FontMetadata } from "../fonts/storage.js";
import type { RenderPixels } from "./client.js";

/** Scan conversion, independent of fitting and bitmap layout. */
export type Rasterization = "free_type_mono" | "coverage";

export interface RenderPipeline {
  fitting: StemFitting | "source_relative" | "font_hints_auto";
  rasterization: Rasterization | "free_type_mono_terminals";
  // Opt-in native diagonal-width fitting; absent unless mono 1-bit opted in.
  diagonal_fitting?: boolean;
}

/** Historical bundled pipeline identity; new requests select explicit stages. */
export type RendererRole = "baseline" | "reference" | "candidate";

/** Candidate 1-bit stem-fitting strategies (`stem_fitting`). */
export type StemFitting = "font_hints_first" | "upstream_mono";

/** Manual monochrome dropout correction (`mono_raster.dropout`). */
export type MonoDropout = "off" | "simple" | "smart";

/** Manual monochrome scan-converter settings (`mono_raster`). */
export interface MonoRaster {
  dropout: MonoDropout;
  includeStubs: boolean;
  fontInstructions: boolean;
}

/** Published output profiles distinguished by the interactive controls. */
export type OutputProfile = "mono_1bit" | "gray_2bit" | "gray_3bit" | "gray_4bit";

/**
 * RGBA color with byte channels 0..255. Readonly inputs are accepted;
 * request mapping always clones into fresh mutable tuples.
 */
export type RGBA = readonly [number, number, number, number];

/**
 * Exact request object for Font.render. The Rust side rejects unknown
 * fields, so this is the complete accepted shape; only `text`, `width`
 * and `height` lack serde defaults and must always be sent.
 */
export interface RenderSpec {
  text: string;
  width: number;
  height: number;
  size_px: number;
  axes: Record<string, number>;
  hinting: "none" | "auto" | "interpreter" | "auto_fallback";
  output_bits: number;
  mono_threshold: number;
  gray_gamma: number;
  missing_glyphs: "error" | "skip";
  kerning: boolean;
  metric_rounding: "subpixel" | "pixel";
  wrap: "clip" | "word" | "char";
  align: "left" | "center" | "right";
  foreground: [number, number, number, number];
  background: [number, number, number, number];
  palette?: [number, number, number, number][];
  renderer?: RendererRole;
  letter_spacing_px: number;
  pipeline?: RenderPipeline;
  stem_fitting?: StemFitting;
  mono_raster?: { dropout: MonoDropout; include_stubs: boolean; font_instructions: boolean };
}

export interface PlaydateExportRequest {
  config: Pick<RenderSpec, "size_px" | "axes" | "hinting" | "output_bits" | "mono_threshold" |
    "gray_gamma" | "missing_glyphs" | "kerning" | "metric_rounding" | "mono_raster"> & { characters: string };
  pipeline: RenderPipeline;
  letter_spacing_px: number;
}

/** Narrow replaceable renderer surface. The worker runtime satisfies it
 * structurally; deterministic fakes implement it in tests and stories. It
 * lives in this type-only module (not the .tsx provider) so plain .ts
 * surfaces such as the fixture and the worker runtime can import it. */
export interface RendererService {
  ping(): Promise<{ available: boolean }>;
  inspect(bytes: ArrayBuffer): Promise<FontMetadata>;
  load(fontId: string, bytes: ArrayBuffer): Promise<void>;
  unload(fontId: string): Promise<void>;
  kerning(fontId: string, sizePx: number, axes: Record<string, number>): Promise<unknown>;
  exportPlaydate(fontId: string, request: PlaydateExportRequest): Promise<ArrayBuffer>;
  nextToken(): number;
  render(fontId: string, token: number, spec: RenderSpec): Promise<{
    token: number;
    dropped: boolean;
    pixels: RenderPixels;
  }>;
  terminate(): void;
}
import * as React from "react";

export type HmrStatus = "connecting" | "connected" | "disconnected";

const PING = "glypherie:hmr-ping";
const PONG = "glypherie:hmr-pong";

export function useHmrStatus(): HmrStatus {
  const hot = import.meta.hot;
  const [status, setStatus] = React.useState<HmrStatus>(() =>
    hot ? (hot.data.hmrStatus as HmrStatus | undefined) ?? "connecting" : "connecting",
  );
  React.useEffect(() => {
    if (!hot) return;
    const retain = (next: HmrStatus): void => {
      hot.data.hmrStatus = next;
      setStatus(next);
    };
    const connected = (): void => retain("connected");
    const disconnected = (): void => retain("disconnected");
    hot.on("vite:ws:connect", connected);
    hot.on("vite:ws:disconnect", disconnected);
    hot.on(PONG, connected);
    // https://vite.dev/guide/api-hmr.html — ws:connect may fire before this
    // effect subscribes, so ask the server for a pong to learn the live state.
    try {
      hot.send(PING);
    } catch {
      // Socket not open yet; the ws:connect listener covers this path.
    }
    return () => {
      hot.off("vite:ws:connect", connected);
      hot.off("vite:ws:disconnect", disconnected);
      hot.off(PONG, connected);
    };
  }, [hot]);
  return status;
}

