      key,
      fontId,
      estimate: measured.estimate,
      cap: measured.cap,
      specForHeight,
      contentHeight: layoutHeight,
      debounceMs,
      immediate: !textChanged,
      nextToken: () => current.nextToken(),
      render: (id, token, spec) => current.render(id, token, spec),
