.site-footer__development { display: inline-flex; align-items: center; gap: 8px; }
.site-footer__details { position: relative; }
.site-footer__details summary { cursor: pointer; list-style: none; flex-wrap: wrap; gap: 4px 10px; }
.site-footer__details summary::-webkit-details-marker { display: none; }
.site-footer__details summary:hover { color: var(--studio-foreground); }
.site-footer__details summary:focus-visible { outline: 2px solid var(--ring); outline-offset: 4px; border-radius: 2px; }
.site-footer__info {
  position: absolute;
  bottom: calc(100% + 12px);
  left: 0;
  width: min(360px, calc(100vw - 32px));
  border: 1px solid var(--studio-border);
  border-radius: 8px;
  padding: 14px;
  background: var(--studio-surface);
  color: var(--studio-foreground);
  box-shadow: var(--studio-card-shadow);
}
.site-footer__info dl { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 6px 14px; margin: 0 0 12px; }
.site-footer__info dt { color: var(--studio-muted); }
.site-footer__info dd { margin: 0; overflow-wrap: anywhere; }
.site-footer__info [role="status"] { margin-left: 8px; }
.site-footer__updates { flex-wrap: wrap; gap: 4px 12px; }
.site-footer .site-footer__version-button, .site-footer .site-footer__update-button {
  height: 22px;
  border: 1px solid var(--studio-border);
  border-radius: 9999px;
  background: var(--studio-inset);
  box-shadow: var(--studio-inset-shadow);
  font: inherit;
  font-weight: 700;
  color: var(--studio-heading);
}
@media (min-width: 1024px) {
  .app-shell { height: 100dvh; overflow: hidden; }
  .app-shell__page { min-height: 0; overflow-y: auto; }
  .app-shell__page > .flex { height: 100%; }
}
@media (max-width: 639px) {
  .site-footer { flex-wrap: wrap; padding: 8px 16px; }
  .site-footer__identity { flex-wrap: wrap; gap: 6px 12px; }
  .site-footer__updates { justify-content: flex-start; }
  .site-footer__details { position: static; }
  .site-footer__info { left: 16px; bottom: calc(100% + 8px); }
}

